def max_participants(n, k, x):
    # Create a dictionary to map each person to the list of people they depend on
    dependency = {}
    for i in range(n):
        if x[i] - 1 not in dependency:
            dependency[x[i] - 1] = []
        dependency[x[i] - 1].append(i)

    # Function to check if a subset of participants can join
    def can_join(subset):
        visited = [False] * n
        stack = subset[:]
        while stack:
            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                if current in dependency:
                    stack.extend(dependency[current])
        return sum(visited) == len(subset)

    # Binary search to find the maximum number of participants that can join
    left, right = 0, min(k, n)
    while left < right:
        mid = (left + right + 1) // 2
        for start in range(n):
            if can_join(range(start, start + mid)):
                left = mid
                break
        else:
            right = mid - 1

    return left

