def max_participants(n, k, preferences):
    graph = defaultdict(list)

    # Build the graph
    for i, pref in enumerate(preferences, start=1):
        if pref != i:
            graph[pref].append(i)

    def dfs(node):
        visited[node] = True
        count = 1
        for neighbor in graph[node]:
            if not visited[neighbor]:
                count += dfs(neighbor)
        return count

    visited = [False] * (n + 1)
    groups = []

    for i in range(1, n + 1):
        if not visited[i]:
            groups.append(dfs(i))

    return min(sum(sorted(groups)[-k:]), n)

