def max_participants(n, k, preferences):
    groups = set()
    visited = [False] * (n + 1)

    def dfs(i):
        if visited[i]:
            return set()
        visited[i] = True
        group = {i}
        for j in range(n):
            if preferences[j] == i:
                group.update(dfs(preferences[j]))
        return group

    for i in range(n):
        if not visited[i]:
            groups.add(tuple(sorted(dfs(i))))

    min_size_group = min(len(group) for group in groups)
    return min(k, len(groups) * min_size_group)

